<?php $pageTitle='Reports';require '../includes/admin-header.php';$pdo=db();$sales=$pdo->query("SELECT COALESCE(SUM(total_amount),0) sales,COUNT(*) orders FROM orders WHERE payment_status='paid'")->fetch();$users=$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn();$best=$pdo->query('SELECT name,sales_count FROM products ORDER BY sales_count DESC LIMIT 5')->fetchAll();$low=$pdo->query('SELECT name,stock_quantity FROM products WHERE stock_quantity<=8 ORDER BY stock_quantity')->fetchAll();$collections=$pdo->query('SELECT c.name,COALESCE(SUM(oi.quantity*oi.unit_price),0) sales FROM categories c LEFT JOIN products p ON p.category_id=c.id LEFT JOIN order_items oi ON oi.product_id=p.id GROUP BY c.id ORDER BY sales DESC')->fetchAll(); ?><div class="row g-3 mb-4"><div class="col-md-4"><div class="card card-body"><small>Total sales</small><b class="fs-3"><?=money($sales['sales'])?></b></div></div><div class="col-md-4"><div class="card card-body"><small>Total orders</small><b class="fs-3"><?=$sales['orders']?></b></div></div><div class="col-md-4"><div class="card card-body"><small>Total users</small><b class="fs-3"><?=$users?></b></div></div></div><div class="row g-4"><div class="col-md-6"><div class="card card-body"><h5>Best-selling T-shirts</h5><?php foreach($best as $x): ?><p class="d-flex justify-content-between border-bottom pb-2"><?=e($x['name'])?><b><?=$x['sales_count']?> sold</b></p><?php endforeach ?></div></div><div class="col-md-6"><div class="card card-body"><h5>Sales by collection</h5><?php foreach($collections as $x): ?><p class="d-flex justify-content-between border-bottom pb-2"><?=e($x['name'])?><b><?=money($x['sales'])?></b></p><?php endforeach ?></div></div></div><?php require '../includes/admin-footer.php'; ?>
